// exhausted/publishPending 과 같은 원칙(끝났다 ≠ 성공했다).
function evidenceUnresolved(evidence?: string): boolean {
  return !!evidence && /미확인|확인되지\s*않|확인하지\s*못/.test(evidence)
}

